class Solution {
        private int rows, cols;
            private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

                public boolean containsCycle(char[][] grid) {
                        rows = grid.length;
                                cols = grid[0].length;
                                        boolean[][] visited = new boolean[rows][cols];

                                                for (int r = 0; r < rows; r++) {
                                                            for (int c = 0; c < cols; c++) {
                                                                            if (!visited[r][c]) {
                                                                                                if (dfs(grid, visited, r, c, -1, -1)) {
                                                                                                                        return true;
                                                                                                                                            }
                                                                                                                                                            }
                                                                                                                                                                        }
                                                                                                                                                                                }
                                                                                                                                                                                        return false;
                                                                                                                                                                                            }

                                                                                                                                                                                                private boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int pr, int pc) {
                                                                                                                                                                                                        visited[r][c] = true;

                                                                                                                                                                                                                for (int[] dir : DIRS) {
                                                                                                                                                                                                                            int nr = r + dir[0];
                                                                                                                                                                                                                                        int nc = c + dir[1];

                                                                                                                                                                                                                                                    // Check bounds and character match
                                                                                                                                                                                                                                                                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == grid[r][c]) {
                                                                                                                                                                                                                                                                                // Ignore immediate parent cell
                                                                                                                                                                                                                                                                                                if (nr == pr && nc == pc) {
                                                                                                                                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                    // If adjacent matching cell is already visited, a cycle is found
                                                                                                                                                                                                                                                                                                                                                                    if (visited[nr][nc] || dfs(grid, visited, nr, nc, r, c)) {
                                                                                                                                                                                                                                                                                                                                                                                        return true;
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                    return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                        }
